// Columns of the hub matrix, matched against syncs[].type.
export const KEY_TYPES = [
  { label: 'Workouts', match: /^workouts?\b/i },
  { label: 'Sleep', match: /^sleep\b/i },
  { label: 'HRV', match: /^(hrv|heart rate variability)\b/i },
  { label: 'Heart rate', match: /^heart rate$/i },
  { label: 'Steps', match: /^steps?\b/i },
];

export const syncOf = (guide, key) => guide.syncs.find((s) => key.match.test(s.type));

const listOf = (names, joiner = 'and') => (names.length > 1 ? `${names.slice(0, -1).join(', ')} ${joiner} ${names.at(-1)}` : names[0] ?? '');

// "Workouts, sleep, heart rate and steps" — the key types a device writes in full.
const lower = (label) => (label === 'HRV' ? label : label.toLowerCase());
export function syncSummary(guide) {
  const full = KEY_TYPES.filter((k) => syncOf(guide, k)?.ok === true).map((k) => lower(k.label));
  const part = KEY_TYPES.filter((k) => syncOf(guide, k)?.ok === 'partial').map((k) => lower(k.label));
  const text = [full.length && listOf(full), part.length && `partly ${listOf(part)}`].filter(Boolean).join('; ') || 'none of the key data types';
  return text.charAt(0).toUpperCase() + text.slice(1);
}

export const formatChecked = (iso) =>
  new Date(`${iso}T12:00:00Z`).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' });

// Meta description from the direct answer: whole sentences up to ~160 characters,
// otherwise the first ones cut at a word. A leading "Yes, one way." adds nothing in a snippet.
export function guideDescription(guide) {
  const answer = guide.answer.join(' ').replace(/^(?:Yes|Partly)\b[^.!?]{0,20}[.!?]\s+/, '');
  const sentences = answer.split(/(?<=[.!?][’'”"]?)\s+/);
  let text = '';
  for (const s of sentences) {
    if (`${text} ${s}`.trim().length > 160) break;
    text = `${text} ${s}`;
  }
  text = text.trim();
  if (text.length >= 90) return text;
  return answer.length <= 160 ? answer : `${answer.slice(0, 158).replace(/[\s,;:]+\S*$/, '')}…`;
}

